// Quests — daily draw fixtures generated by the BOT's quest-engine.

import { describe, expect, it, vi } from 'vitest'
import {
  DAILY_COUNT,
  dailyQuestIdsForDay,
  ensureQuestState,
  recordQuestEvent,
  getQuestBoard,
  claimableCount,
  claimQuest,
  payReward,
} from '../src/engine/quests'
import { createNewPlayer } from '../src/state/player'

// Bot-run fixtures (quest-engine dailyQuestIdsForDay).
const FIXTURES: [number, string[]][] = [
  [Date.UTC(2026, 0, 1), ['d_level_1', 'd_pvp_2', 'd_floor_20']],
  [Date.UTC(2026, 5, 15), ['d_pvp_2', 'd_catch_5', 'd_catch_3']],
  [Date.UTC(2026, 10, 25), ['d_floor_20', 'd_poke_3', 'd_level_1']],
  [Date.UTC(2024, 1, 29), ['d_pvp_2', 'd_floor_10', 'd_floor_20']],
]

function fresh() {
  return createNewPlayer({ name: 'QuestTester', classId: 'warrior', raceId: 'human' })
}

describe('seeded daily draw (bot parity)', () => {
  it('DAILY_COUNT is 3', () => {
    expect(DAILY_COUNT).toBe(3)
  })

  it('matches bot output for four calendar days', () => {
    for (const [day, expected] of FIXTURES) {
      expect(dailyQuestIdsForDay(day)).toEqual(expected)
    }
  })

  it('is stable within a day and rotates at midnight', () => {
    const day = Date.UTC(2026, 5, 15)
    expect(dailyQuestIdsForDay(day)).toEqual(dailyQuestIdsForDay(day + 3600_000))
    expect(dailyQuestIdsForDay(day)).not.toEqual(dailyQuestIdsForDay(day + 86_400_000))
  })
})

describe('state + rotation', () => {
  it('rotating the day wipes daily progress but keeps lifetime and milestones', () => {
    const p = fresh()
    const q = ensureQuestState(p, Date.UTC(2026, 5, 15))
    q.daily['d_level_1'] = 1
    q.dailyClaimed.push('d_level_1')
    q.lifetime['kill'] = 7
    q.milestoneClaimed.push('m_kill_10')

    ensureQuestState(p, Date.UTC(2026, 5, 16)) // next day
    expect(p.quests.daily).toEqual({})
    expect(p.quests.dailyClaimed).toEqual([])
    expect(p.quests.lifetime['kill']).toBe(7)
    expect(p.quests.milestoneClaimed).toEqual(['m_kill_10'])
  })

  it('recordQuestEvent advances matching dailies for today and crosses goals', () => {
    // recordQuestEvent re-seeds via Date.now() (rotation is wall-clock driven,
    // like the bot) — freeze the clock so the fixed-day draw below is the one
    // under test instead of whenever this suite happens to run.
    const nowSpy = vi.spyOn(Date, 'now').mockReturnValue(Date.UTC(2026, 0, 1))
    try {
      const p = fresh()
      ensureQuestState(p, Date.UTC(2026, 0, 1)) // draw: d_level_1, d_pvp_2, d_floor_20
      const crossed = recordQuestEvent(p, 'floor', 10)
      expect(p.quests.lifetime['floor']).toBe(10)
      expect(crossed.some((c) => c.def.id === 'd_floor_20')).toBe(false) // goal 20 not reached
      const crossed2 = recordQuestEvent(p, 'floor', 10)
      expect(crossed2.some((c) => c.track === 'daily' && c.def.id === 'd_floor_20')).toBe(true)
      // non-matching metric only touches lifetime
      recordQuestEvent(p, 'catch', 3)
      expect(p.quests.lifetime['catch']).toBe(3)
      expect(p.quests.daily['d_floor_20']).toBe(20)
      // no double-cross once complete
      expect(recordQuestEvent(p, 'floor', 5).some((c) => c.def.id === 'd_floor_20')).toBe(false)
    } finally {
      nowSpy.mockRestore()
    }
  })
})

describe('claim pays explicitly', () => {
  it('completing does not pay; claiming pays exactly the quest reward once', () => {
    const p = fresh()
    ensureQuestState(p) // today's real draw (claims rotate on Date.now, like the bot)
    const target = getQuestBoard(p).daily[0]! // any of today's three
    const before = { ...p.wallet }
    const xpBefore = p.xp

    recordQuestEvent(p, target.metric, target.goal)
    // nothing is paid passively — completion only unlocks the claim
    expect(p.wallet.solars).toBe(before.solars)
    expect(p.wallet.gems).toBe(before.gems)
    expect(p.xp).toBe(xpBefore)
    expect(getQuestBoard(p).daily.find((q) => q.id === target.id)!.done).toBe(true)
    expect(claimableCount(p)).toBeGreaterThanOrEqual(1)

    const res = claimQuest(p, target.id)
    expect(res.claimed).toHaveLength(1)
    expect(res.claimed[0]!.id).toBe(target.id)
    expect(res.claimed[0]!.rewardLabel).toBeTruthy()
    const amt = target.reward.amount
    if (target.reward.type === 'solars') expect(p.wallet.solars).toBe(before.solars + amt)
    else if (target.reward.type === 'gems') expect(p.wallet.gems).toBe(before.gems + amt)
    else if (target.reward.type === 'xp') expect(p.xp).toBe(xpBefore + amt)
    expect(p.quests.dailyClaimed).toContain(target.id)

    // claiming twice pays once
    expect(claimQuest(p, target.id).nothing).toBe(true)
    if (target.reward.type === 'solars') expect(p.wallet.solars).toBe(before.solars + amt)
    else if (target.reward.type === 'gems') expect(p.wallet.gems).toBe(before.gems + amt)
    else if (target.reward.type === 'xp') expect(p.xp).toBe(xpBefore + amt)
  })

  it('claim all pays every done quest across both tracks', () => {
    const p = fresh()
    ensureQuestState(p, Date.UTC(2026, 0, 1))
    recordQuestEvent(p, 'floor', 20)
    recordQuestEvent(p, 'kill', 10) // lifetime feeds milestones
    const res = claimQuest(p)
    expect(res.claimed.length).toBeGreaterThanOrEqual(1)
    expect(res.nothing).toBe(false)
    expect(claimQuest(p).nothing).toBe(true)
  })
})

describe('payReward vocabulary (V0)', () => {
  it('pays solars/gems/xp/stamina and grants items/characters', () => {
    const p = fresh() as unknown as {
      wallet: { solars: number; gems: number }
      xp: number
      stamina: { current: number; max: number }
      inventory: string[]
      ownedCharacters: string[]
    }
    expect(payReward(p, { type: 'solars', amount: 400 })).toContain('400')
    expect(p.wallet.solars).toBe(500) // 100 start + 400
    expect(payReward(p, { type: 'gems', amount: 5 })).toContain('5')
    expect(p.wallet.gems).toBe(5)
    expect(payReward(p, { type: 'xp', amount: 500 })).toContain('500')
    expect(p.xp).toBe(500)
    p.stamina.current = 5
    payReward(p, { type: 'stamina', amount: 10 })
    expect(p.stamina.current).toBe(15)
    payReward(p, { type: 'weapon', amount: 1, itemId: 'iron_sword' })
    expect(p.inventory).toContain('iron_sword')
    payReward(p, { type: 'character', amount: 1, itemId: 'the_end' })
    expect(p.ownedCharacters).toContain('the_end')
    expect(payReward(p, { type: 'seasonPoints', amount: 1 })).toBeNull()
    expect(payReward(p, null)).toBeNull()
  })
})
